views 'C2' {
  view c2_corePlatform {
    title 'Core Platform - Container View'

    // Parent boundary + actor + external dependency
    include customer
    include corePlatform
    include externalEmailService

    // Focus internals (containers)
    include corePlatform.*

    // Neighbors (incoming + outgoing around the focus)
    include -> corePlatform
    include corePlatform ->

    // Drill-down from the web app to a C3 detail
    include corePlatform.webApplication with {
      navigateTo c3_webApplication
    }
  }
}

views 'Deployment' {
  deployment view production_overview {
    title 'Production Infrastructure'

    // Environment
    include production

    // Zones / tiers
    include production.dmzTier
    include production.appTier
    include production.dataTier

    // VMs (explicit)
    include production.dmzTier.webVm
    include production.dmzTier.edgeFirewallVm
    include production.appTier.apiVm
    include production.appTier.workerVm
    include production.dataTier.dbVm
    include production.dataTier.backupVm
  }
}

views 'Use Cases' {
  dynamic view uc_uploadJourney {
    title 'Upload Journey'

    customer -> corePlatform.webApplication 'Select file and submit'
    corePlatform.webApplication -> corePlatform.uploadService 'POST /uploads'
    corePlatform.uploadService -> corePlatform.storageAdapter 'Store binary'
    corePlatform.uploadService -> corePlatform.virusScanner 'Scan uploaded file'
    corePlatform.uploadService -> corePlatform.notificationService 'Publish upload-complete event'
  }
}

views 'C2' {
  view c2_security_boundary {
    title 'Security-Relevant Container Context'
    include operator
    include corePlatform
    include corePlatform.*
    include externalIdentityProvider
    include -> corePlatform
    include corePlatform ->
  }
}

views 'Deployment' {
  deployment view production_secZone {
    title 'Production SecZone Topology'

    include production
    include production.secZone

    include production.secZone.bastionVm
    include production.secZone.firewallVm
    include production.secZone.authServiceVm
    include production.secZone.auditServiceVm
  }
}

